-- Synthetic shared example journal. No credentials or real observations.
CREATE TABLE demo_datasets (
  id TEXT PRIMARY KEY,
  owner_id TEXT NOT NULL UNIQUE REFERENCES users(id),
  title TEXT NOT NULL,
  anchor_date TEXT NOT NULL,
  record_count INTEGER NOT NULL CHECK(record_count > 0)
);
CREATE TRIGGER protect_demo_insert BEFORE INSERT ON entries WHEN NEW.owner_id IN (SELECT owner_id FROM demo_datasets) BEGIN SELECT RAISE(ABORT, 'Shared demo records are immutable'); END;
CREATE TRIGGER protect_demo_update BEFORE UPDATE ON entries WHEN OLD.owner_id IN (SELECT owner_id FROM demo_datasets) OR NEW.owner_id IN (SELECT owner_id FROM demo_datasets) BEGIN SELECT RAISE(ABORT, 'Shared demo records are immutable'); END;
CREATE TRIGGER protect_demo_delete BEFORE DELETE ON entries WHEN OLD.owner_id IN (SELECT owner_id FROM demo_datasets) BEGIN SELECT RAISE(ABORT, 'Shared demo records are immutable'); END;
CREATE TRIGGER prevent_demo_login BEFORE INSERT ON auth_accounts WHEN NEW.user_id IN (SELECT owner_id FROM demo_datasets) BEGIN SELECT RAISE(ABORT, 'Demo owners cannot sign in'); END;
CREATE TRIGGER prevent_demo_login_update BEFORE UPDATE OF user_id ON auth_accounts WHEN NEW.user_id IN (SELECT owner_id FROM demo_datasets) BEGIN SELECT RAISE(ABORT, 'Demo owners cannot sign in'); END;
